package org.beehive.jitnn.kernels;

import uk.ac.manchester.tornado.api.KernelContext;
import uk.ac.manchester.tornado.api.math.TornadoMath;
import uk.ac.manchester.tornado.api.types.arrays.FloatArray;
import uk.ac.manchester.tornado.api.types.arrays.IntArray;

/**
 * Multi-tensor kernels, generated by scripts/codegen/multi_tensor.py: the optimiser updates of up
 * to 4 parameters, and the gradient statistics of up to 8 gradients, in one launch each. Thread i
 * of an update belongs to the slot whose range [start, start + sizes[slot]) holds it; unused
 * slots have size 0. {@code stats} = [norm, factor, skip] as in {@link LowPrecision#gradStats}.
 */
public final class MultiTensorKernels {

    /** Tensors per optimiser launch. */
    public static final int OPT_SLOTS = 4;
    /** Gradients per statistics launch (one work-group each). */
    public static final int STATS_SLOTS = 8;
    private static final int GROUP = 256;

    private MultiTensorKernels() {
    }

    private static void adamAt(FloatArray p, FloatArray g, FloatArray m, FloatArray v, FloatArray hyper, float factor, int i) {
        float lr = hyper.get(0);
        float b1 = hyper.get(1);
        float b2 = hyper.get(2);
        float wd = hyper.get(6);
        float w = p.get(i);
        float grad = g.get(i) * factor;
        if (hyper.get(7) != 0.0f) {
            w = w - lr * wd * w;
        } else {
            grad = grad + wd * w;
        }
        float mi = b1 * m.get(i) + (1.0f - b1) * grad;
        float vi = b2 * v.get(i) + (1.0f - b2) * grad * grad;
        m.set(i, mi);
        v.set(i, vi);
        p.set(i, w - lr * (mi / hyper.get(4)) / (TornadoMath.sqrt(vi / hyper.get(5)) + hyper.get(3)));
    }

    private static void sgdAt(FloatArray p, FloatArray g, FloatArray hyper, float factor, int i) {
        float w = p.get(i);
        p.set(i, w - hyper.get(0) * (g.get(i) * factor + hyper.get(2) * w));
    }

    private static void momentumAt(FloatArray p, FloatArray g, FloatArray buf, FloatArray hyper, float factor, int i) {
        float w = p.get(i);
        float mu = hyper.get(1);
        float grad = g.get(i) * factor + hyper.get(2) * w;
        float v = mu * buf.get(i) + grad;
        buf.set(i, v);
        float step = hyper.get(3) != 0.0f ? grad + mu * v : v;
        p.set(i, w - hyper.get(0) * step);
    }

    /** Adam, or AdamW when hyper[7] != 0, over 4 parameters; hyper = [lr, beta1, beta2, eps, 1 - beta1^t, 1 - beta2^t, weightDecay, decoupled]. */
    public static void adam(KernelContext kc, FloatArray p0, FloatArray g0, FloatArray m0, FloatArray v0, FloatArray p1, FloatArray g1, FloatArray m1, FloatArray v1, FloatArray p2, FloatArray g2, FloatArray m2, FloatArray v2, FloatArray p3, FloatArray g3, FloatArray m3, FloatArray v3, FloatArray hyper, FloatArray stats, IntArray sizes) {
        int i = kc.globalIdx;
        if (stats.get(2) == 0.0f) {
            float factor = stats.get(1);
            int s0 = 0;
            int s1 = s0 + sizes.get(0);
            int s2 = s1 + sizes.get(1);
            int s3 = s2 + sizes.get(2);
            if ((i >= s0) & (i < s0 + sizes.get(0))) {
                adamAt(p0, g0, m0, v0, hyper, factor, i - s0);
            } else if ((i >= s1) & (i < s1 + sizes.get(1))) {
                adamAt(p1, g1, m1, v1, hyper, factor, i - s1);
            } else if ((i >= s2) & (i < s2 + sizes.get(2))) {
                adamAt(p2, g2, m2, v2, hyper, factor, i - s2);
            } else if ((i >= s3) & (i < s3 + sizes.get(3))) {
                adamAt(p3, g3, m3, v3, hyper, factor, i - s3);
            }
        }
    }

    /** SGD over 4 parameters; hyper = [lr, momentum, weightDecay, nesterov]. */
    public static void sgd(KernelContext kc, FloatArray p0, FloatArray g0, FloatArray p1, FloatArray g1, FloatArray p2, FloatArray g2, FloatArray p3, FloatArray g3, FloatArray hyper, FloatArray stats, IntArray sizes) {
        int i = kc.globalIdx;
        if (stats.get(2) == 0.0f) {
            float factor = stats.get(1);
            int s0 = 0;
            int s1 = s0 + sizes.get(0);
            int s2 = s1 + sizes.get(1);
            int s3 = s2 + sizes.get(2);
            if ((i >= s0) & (i < s0 + sizes.get(0))) {
                sgdAt(p0, g0, hyper, factor, i - s0);
            } else if ((i >= s1) & (i < s1 + sizes.get(1))) {
                sgdAt(p1, g1, hyper, factor, i - s1);
            } else if ((i >= s2) & (i < s2 + sizes.get(2))) {
                sgdAt(p2, g2, hyper, factor, i - s2);
            } else if ((i >= s3) & (i < s3 + sizes.get(3))) {
                sgdAt(p3, g3, hyper, factor, i - s3);
            }
        }
    }

    /** SGD with (optionally Nesterov) momentum, dampening 0, over 4 parameters; hyper as sgd. */
    public static void sgdMomentum(KernelContext kc, FloatArray p0, FloatArray g0, FloatArray b0, FloatArray p1, FloatArray g1, FloatArray b1, FloatArray p2, FloatArray g2, FloatArray b2, FloatArray p3, FloatArray g3, FloatArray b3, FloatArray hyper, FloatArray stats, IntArray sizes) {
        int i = kc.globalIdx;
        if (stats.get(2) == 0.0f) {
            float factor = stats.get(1);
            int s0 = 0;
            int s1 = s0 + sizes.get(0);
            int s2 = s1 + sizes.get(1);
            int s3 = s2 + sizes.get(2);
            if ((i >= s0) & (i < s0 + sizes.get(0))) {
                momentumAt(p0, g0, b0, hyper, factor, i - s0);
            } else if ((i >= s1) & (i < s1 + sizes.get(1))) {
                momentumAt(p1, g1, b1, hyper, factor, i - s1);
            } else if ((i >= s2) & (i < s2 + sizes.get(2))) {
                momentumAt(p2, g2, b2, hyper, factor, i - s2);
            } else if ((i >= s3) & (i < s3 + sizes.get(3))) {
                momentumAt(p3, g3, b3, hyper, factor, i - s3);
            }
        }
    }

    /**
     * Sum of squares and a NaN/infinity flag of up to 8 gradients: work-group k writes
     * partial[2 (slot0 + k)] and partial[2 (slot0 + k) + 1]. Launch 8 groups of 256 threads.
     */
    public static void sumSquaresFinite(KernelContext kc, FloatArray g0, FloatArray g1, FloatArray g2, FloatArray g3, FloatArray g4, FloatArray g5, FloatArray g6, FloatArray g7, FloatArray partial, IntArray sizes, int slot0) {
        float[] sq = kc.allocateFloatLocalArray(GROUP);
        int[] bad = kc.allocateIntLocalArray(GROUP);
        int l = kc.localIdx;
        int k = kc.groupIdx;
        int n = sizes.get(k);
        float s = 0.0f;
        int b = 0;
        if (k == 0) {
            for (int i = l; i < n; i += GROUP) {
                float x = g0.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        } else if (k == 1) {
            for (int i = l; i < n; i += GROUP) {
                float x = g1.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        } else if (k == 2) {
            for (int i = l; i < n; i += GROUP) {
                float x = g2.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        } else if (k == 3) {
            for (int i = l; i < n; i += GROUP) {
                float x = g3.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        } else if (k == 4) {
            for (int i = l; i < n; i += GROUP) {
                float x = g4.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        } else if (k == 5) {
            for (int i = l; i < n; i += GROUP) {
                float x = g5.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        } else if (k == 6) {
            for (int i = l; i < n; i += GROUP) {
                float x = g6.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        } else if (k == 7) {
            for (int i = l; i < n; i += GROUP) {
                float x = g7.get(i);
                s += x * x;
                b = b | LowPrecision.nonFinite(x);
            }
        }
        sq[l] = s;
        bad[l] = b;
        kc.localBarrier();
        for (int r = GROUP / 2; r > 0; r = r / 2) {
            if (l < r) {
                sq[l] = sq[l] + sq[l + r];
                bad[l] = bad[l] | bad[l + r];
            }
            kc.localBarrier();
        }
        if ((l == 0) & (n > 0)) {
            partial.set(2 * (slot0 + k), sq[0]);
            partial.set(2 * (slot0 + k) + 1, bad[0]);
        }
    }
}
